<?php
declare(strict_types=1);
namespace Sigta\Controllers;
use Sigta\Core\{Auth,Db,Http};
use Sigta\Services\Academic;
use Sigta\Views\Layout as L;
final class PortalController {
    private static function apps(int $limit=100):array {
        $limit=max(1,min(200,$limit));
        $base='SELECT a.id,a.topic,a.status,a.created_at,a.updated_at,a.student_id,u.full_name student,m.name modality,c.name career FROM applications a JOIN users u ON u.id=a.student_id JOIN modalities m ON m.id=a.modality_id JOIN students st ON st.user_id=a.student_id JOIN careers c ON c.id=st.career_id';
        if(Auth::has('admin'))return Db::all($base.' ORDER BY a.updated_at DESC LIMIT '.$limit);
        if(Auth::has('director','secretaria'))return Db::all($base.' WHERE EXISTS (SELECT 1 FROM staff_careers sc WHERE sc.career_id=st.career_id AND sc.user_id=?) ORDER BY a.updated_at DESC LIMIT '.$limit,[Auth::id()]);
        if(Auth::has('estudiante'))return Db::all($base.' WHERE a.student_id=? ORDER BY a.updated_at DESC LIMIT '.$limit,[Auth::id()]);
        return Db::all($base.' WHERE EXISTS (SELECT 1 FROM assignments ass WHERE ass.application_id=a.id AND ass.teacher_id=? AND ass.ended_at IS NULL) ORDER BY a.updated_at DESC LIMIT '.$limit,[Auth::id()]);
    }
    public static function dashboard():void {
        Auth::require();$apps=self::apps();$counts=[];foreach($apps as $app)$counts[$app['status']]=($counts[$app['status']]??0)+1;
        $pending=Db::one('SELECT COUNT(*) n FROM notifications WHERE user_id=? AND read_at IS NULL',[Auth::id()]);
        ob_start();echo '<section class="welcome-banner"><div><div class="eyebrow">CENTRO DE GESTIÓN ACADÉMICA</div><h2>Bienvenido a tu espacio de titulación</h2><p>Consulta procesos, verifica avances y administra responsabilidades con información centralizada.</p></div><div class="banner-art" aria-hidden="true"><div class="art-circle"><span>✓</span></div></div></section><div class="stat-grid">';
        foreach([['Expedientes visibles',count($apps),'▤'],['En seguimiento',($counts['en_desarrollo']??0)+($counts['aprobada']??0),'◈'],['Habilitados',($counts['habilitada']??0),'◎'],['Avisos pendientes',$pending['n'],'◉']] as [$label,$value,$icon])echo '<div class="stat-card"><div class="stat-icon">'.$icon.'</div><div><span>'.L::e($label).'</span><strong>'.L::e($value).'</strong></div></div>';
        echo '</div><section class="card"><div class="section-heading"><div><h2>Actividad reciente</h2><p>Últimos expedientes a los que tienes acceso.</p></div><a class="button secondary" href="'.Http::url('postulaciones').'">Ver todos →</a></div>'.self::table(array_slice($apps,0,8)).'</section>';
        if(Auth::has('estudiante'))echo '<section class="tips"><span>✦</span><p><strong>Recomendación:</strong> revisa los requisitos documentales y conserva las versiones de tus archivos antes de presentar la postulación.</p></section>';
        L::page('Panel general',ob_get_clean(),'Resumen del ciclo de titulación y operaciones disponibles según tu rol.');
    }
    public static function applications():void {
        Auth::require();$apps=self::apps();ob_start();
        echo '<section class="card"><div class="section-heading"><div><h2>Expedientes de titulación</h2><p>Accede al seguimiento, historial y documentos de cada caso.</p></div></div><div class="search-row"><input type="search" placeholder="Buscar por estudiante, tema o modalidad" data-table-filter="#apps-table" aria-label="Filtrar expedientes"></div>'.self::table($apps,'apps-table').'</section>';
        if(Auth::has('estudiante')){
            $student=Db::one('SELECT career_id FROM students WHERE user_id=?',[Auth::id()]);
            if($student){
                $calls=Db::all('SELECT ca.id,ca.title,ca.closes_at FROM calls ca WHERE ca.career_id=? AND ca.active=1 AND NOW() BETWEEN ca.opens_at AND ca.closes_at ORDER BY ca.id DESC',[$student['career_id']]);
                $mods=Db::all('SELECT cm.call_id,m.id,m.name FROM call_modalities cm JOIN modalities m ON m.id=cm.modality_id JOIN calls ca ON ca.id=cm.call_id WHERE ca.career_id=? AND ca.active=1 AND NOW() BETWEEN ca.opens_at AND ca.closes_at ORDER BY m.name',[$student['career_id']]);
                echo '<section class="card"><div class="section-heading"><div><h2>Iniciar una nueva postulación</h2><p>Elige convocatoria y modalidad habilitadas para tu carrera.</p></div></div>';
                if(!$calls)echo '<div class="notice">No existen convocatorias vigentes. Dirección de Carrera debe habilitar una.</div>';
                else echo '<form method="post" action="'.Http::url('postulaciones').'"><div class="form-grid">'.L::csrf().'<label>Convocatoria<select name="call_id" required data-call-select>'.L::option($calls,'id','title').'</select></label><label>Modalidad<select name="modality_id" required data-modalities-select><option value="">Selecciona convocatoria...</option>'.implode('',array_map(fn($m)=>'<option value="'.L::e($m['id']).'" data-call="'.L::e($m['call_id']).'" hidden>'.L::e($m['name']).'</option>',$mods)).'</select></label><label class="span-2">Título del tema<input name="topic" minlength="8" maxlength="220" required placeholder="Ej. Sistema de seguimiento documental de titulación"></label><label class="span-2">Resumen del proyecto<textarea name="abstract" maxlength="2000" rows="4" placeholder="Describe brevemente el alcance, la problemática y el propósito..."></textarea></label></div><button class="button" type="submit">Crear expediente →</button></form>';
                echo '</section>';
            }
        }
        L::page('Postulaciones',ob_get_clean(),'Consulta, filtra y registra procesos de graduación.');
    }
    private static function table(array $apps,string $id=''):string {
        $html='<div class="table-wrap"><table '.($id?'id="'.L::e($id).'"':'').'><thead><tr><th>Expediente</th><th>Estudiante</th><th>Modalidad</th><th>Estado</th><th>Última actualización</th><th></th></tr></thead><tbody>';
        foreach($apps as $a)$html.='<tr><td><strong>'.L::e($a['topic']).'</strong><small class="block">#'.L::e($a['id']).' · '.L::e($a['career']).'</small></td><td>'.L::e($a['student']).'</td><td>'.L::e($a['modality']).'</td><td>'.L::badge($a['status']).'</td><td>'.L::e($a['updated_at']).'</td><td><a class="table-link" href="'.Http::url('postulaciones/'.$a['id']).'">Abrir →</a></td></tr>';
        return $html.($apps?'':'<tr><td colspan="6" class="empty-cell">No hay expedientes disponibles.</td></tr>').'</tbody></table></div>';
    }
    public static function show(int $id):void {
        Auth::require();$a=Academic::application($id);Academic::requireView($a);
        $requirements=Db::all('SELECT rv.*,r.code,r.name FROM requirement_verifications rv JOIN requirements r ON r.id=rv.requirement_id WHERE rv.application_id=? ORDER BY r.name',[$id]);
        $docs=Db::all('SELECT dv.*,dt.name type_name,dt.code type_code,d.milestone_id,docr.decision last_review FROM document_versions dv JOIN documents d ON d.id=dv.document_id JOIN document_types dt ON dt.id=d.document_type_id LEFT JOIN document_reviews docr ON docr.id=(SELECT MAX(dr.id) FROM document_reviews dr WHERE dr.version_id=dv.id) WHERE d.application_id=? ORDER BY dt.name,dv.id DESC',[$id]);
        $assignments=Db::all('SELECT ass.*,u.full_name,ev.sufficient,ev.comments AS evaluation_comments,ev.id AS evaluation_id FROM assignments ass JOIN users u ON u.id=ass.teacher_id LEFT JOIN evaluations ev ON ev.assignment_id=ass.id WHERE ass.application_id=? AND ass.ended_at IS NULL ORDER BY ass.role_code,ass.seat',[$id]);
        $milestones=Db::all('SELECT * FROM milestones WHERE application_id=? ORDER BY sequence_no',[$id]);
        $def=Db::one('SELECT d.*,r.name room_name,ac.id act_id,ac.final_grade FROM defenses d JOIN rooms r ON r.id=d.room_id LEFT JOIN acts ac ON ac.defense_id=d.id WHERE d.application_id=?',[$id]);
        $resolution=Db::one('SELECT id,final_grade FROM resolutions WHERE application_id=?',[$id]);
        $binding=Db::one('SELECT id FROM binding_authorizations WHERE application_id=?',[$id]);
        $owner=Auth::id()===(int)$a['student_id'];$manager=Auth::has('director','admin');$secretariat=Auth::has('secretaria','director','admin');
        $teacher=Academic::canTeacher($id);$types=Db::all('SELECT id,name,code FROM document_types ORDER BY id');
        ob_start();echo '<div class="detail-top"><div><a class="back-link" href="'.Http::url('postulaciones').'">← Volver a postulaciones</a><div class="eyebrow">EXPEDIENTE #'.L::e($id).' · '.L::e($a['career_name']).'</div><h2>'.L::e($a['topic']).'</h2><p class="muted">'.L::e($a['student_name']).' · '.L::e($a['modality_name']).' · '.L::e($a['call_title']).'</p></div>'.L::badge($a['status']).'</div>';
        echo '<div class="detail-grid"><div class="detail-primary"><section class="card"><div class="section-heading"><div><h3>Estado y seguimiento</h3><p>Información trazable del proceso académico</p></div></div><div class="timeline">';
        $phases=['borrador'=>'Borrador','presentada'=>'Postulación presentada','aprobada'=>'Perfil aprobado','en_desarrollo'=>'En desarrollo','habilitada'=>'Habilitada para defensa','programada'=>'Defensa programada','concluida'=>'Proceso concluido'];
        foreach($phases as $key=>$label)echo '<div class="timeline-item '.($a['status']===$key?'current':'').'"><span class="timeline-dot"></span><span>'.L::e($label).'</span></div>';
        echo '</div><div class="detail-fields"><div><small>Fecha de presentación</small><strong>'.L::e($a['submitted_at']??'Pendiente').'</strong></div><div><small>Último avance</small><strong>'.L::e($a['last_progress_at']??'Sin avance').'</strong></div><div><small>Fecha de aprobación</small><strong>'.L::e($a['approved_at']??'Pendiente').'</strong></div></div>'.($a['decision_note']?'<div class="notice">'.L::e($a['decision_note']).'</div>':'').'</section>';
        if($owner&&in_array($a['status'],['borrador','observada'],true))echo '<section class="card"><h3>Presentar postulación</h3><p class="muted">Adjunta CI, Kardex y perfil (si aplica) antes de enviar.</p><form method="post" action="'.Http::url('postulaciones/'.$id.'/enviar').'">'.L::csrf().'<button class="button" type="submit">Enviar a revisión →</button></form></section>';
        echo '<section class="card"><div class="section-heading"><div><h3>Requisitos académicos</h3><p>Verificación documental previa al proceso académico.</p></div></div><div class="table-wrap"><table><thead><tr><th>Requisito</th><th>Estado</th><th>Verificación</th></tr></thead><tbody>';
        foreach($requirements as $r){echo '<tr><td>'.L::e($r['name']).'</td><td>'.L::badge($r['status']).'</td><td>';if($secretariat)echo '<form class="compact-form" method="post" action="'.Http::url('postulaciones/'.$id.'/requisito').'">'.L::csrf().'<input type="hidden" name="requirement_id" value="'.L::e($r['requirement_id']).'"><select name="status"><option value="pendiente">Pendiente</option><option value="aprobado">Aprobar</option><option value="rechazado">Rechazar</option></select><input name="notes" aria-label="Observación" maxlength="300" placeholder="Observación"><button class="button small" type="submit">Guardar</button></form>';else echo L::e($r['notes']??'En verificación');echo '</td></tr>';}
        echo '</tbody></table></div></section>';
        echo '<section class="card"><div class="section-heading"><div><h3>Documentos y versiones</h3><p>Adjuntos con verificación de tipo, hash SHA-256 y versiones.</p></div></div><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Versión</th><th>Revisión</th><th>Archivo</th></tr></thead><tbody>';
        foreach($docs as $d)echo '<tr><td>'.L::e($d['type_name']).'<small class="block">'.L::e($d['original_filename']).'</small></td><td>v'.L::e($d['version_number']).'</td><td>'.($d['last_review']?L::badge($d['last_review']):'Pendiente').'</td><td><a class="table-link" href="'.Http::url('documentos/'.$d['id'].'/descargar').'">Descargar</a></td></tr>';
        if(!$docs)echo '<tr><td colspan="4" class="empty-cell">Todavía no hay archivos cargados.</td></tr>';echo '</tbody></table></div>';
        if($owner&&in_array($a['status'],['borrador','observada','presentada','aprobada','en_desarrollo','habilitada'],true)){
            echo '<details class="form-details" open><summary>Adjuntar nueva versión</summary><form method="post" enctype="multipart/form-data" action="'.Http::url('postulaciones/'.$id.'/documento').'">'.L::csrf().'<div class="form-grid"><label>Tipo de documento<select name="document_type_id" required>'.L::option($types).'</select></label><label>Hito (solo para informes de avance)<select name="milestone_id"><option value="">Sin hito</option>'.L::option($milestones,'id','title',null).'</select></label><label class="span-2">Archivo<input type="file" name="document" accept=".pdf,.png,.jpg,.jpeg,application/pdf,image/jpeg,image/png" required><small>PDF, JPG o PNG, máximo 8 MB por defecto.</small></label></div><button class="button" type="submit">Guardar documento</button></form></details>';
        }
        if($manager||$teacher){
            $reviewable=($manager||$teacher)&&in_array($a['status'],['presentada','observada','aprobada','en_desarrollo','habilitada'],true);
            if($reviewable){$profile=Db::one("SELECT dv.id,dt.name FROM document_versions dv JOIN documents d ON d.id=dv.document_id JOIN document_types dt ON dt.id=d.document_type_id WHERE d.application_id=? AND dt.code='PERFIL' ORDER BY dv.id DESC LIMIT 1",[$id]);
                $reviewer=(bool)Db::one("SELECT id FROM assignments WHERE application_id=? AND teacher_id=? AND role_code='revisor' AND ended_at IS NULL",[$id,Auth::id()]);
                if($profile&&($manager||$reviewer))echo '<details class="form-details"><summary>Revisar la última versión del perfil</summary><form method="post" action="'.Http::url('documentos/'.$profile['id'].'/revision').'">'.L::csrf().'<label>Decisión<select name="decision"><option value="aprobado">Aprobar</option><option value="observado">Observar</option><option value="rechazado">Rechazar</option></select></label><label>Comentarios<textarea name="comments" required minlength="8" maxlength="1000"></textarea></label><button class="button" type="submit">Registrar revisión</button></form></details>';
            }
        }
        echo '</section>';
        echo '<section class="card"><div class="section-heading"><div><h3>Hitos y seguimiento</h3><p>Control de entregas parciales y fechas comprometidas.</p></div></div>';
        foreach($milestones as $h)echo '<div class="milestone-item"><span class="number-pill">'.L::e($h['sequence_no']).'</span><div><strong>'.L::e($h['title']).'</strong><small class="block">Vence: '.L::e($h['due_at']).'</small></div>'.L::badge($h['status']).'</div>';
        if(!$milestones)echo '<p class="muted">Todavía no se han definido hitos de avance.</p>';
        if($manager||$teacher)echo '<details class="form-details"><summary>Agregar hito</summary><form method="post" action="'.Http::url('postulaciones/'.$id.'/hito').'">'.L::csrf().'<label>Nombre del hito<input name="title" required maxlength="140"></label><label>Vencimiento<input type="datetime-local" name="due_at" required></label><button class="button" type="submit">Crear hito</button></form></details>';
        echo '</section>';
        echo '<section class="card"><div class="section-heading"><div><h3>Tutorías, tribunales y evaluaciones</h3><p>Una misma persona no puede ocupar dos posiciones activas en este proyecto.</p></div></div>';
        $criteria=Db::all('SELECT rc.id,rc.label,rc.weight_percent FROM rubrics r JOIN rubric_criteria rc ON rc.rubric_id=r.id WHERE r.modality_id=? AND r.active=1 ORDER BY rc.id',[$a['modality_id']]);
        foreach($assignments as $ass){echo '<div class="assignment"><div class="assignment-head"><div><strong>'.L::e(ucfirst($ass['role_code'])).' '.($ass['role_code']==='tribunal'?'#'.L::e($ass['seat']):'').'</strong><small class="block">'.L::e($ass['full_name']).'</small></div>'.($ass['evaluation_id']?L::badge((int)$ass['sufficient']?'aprobado':'rechazado'):'<span class="muted">Sin dictamen</span>').'</div>';
            if((int)$ass['teacher_id']===Auth::id()&&in_array($ass['role_code'],['tutor','tribunal'],true)&&in_array($a['status'],['en_desarrollo','habilitada'],true)){
                echo '<details class="form-details"><summary>Emitir dictamen con rúbrica</summary><form method="post" action="'.Http::url('evaluaciones/'.$ass['id']).'">'.L::csrf();foreach($criteria as $c)echo '<label>'.L::e($c['label']).' ('.L::e($c['weight_percent']).'%)<input type="number" name="scores['.L::e($c['id']).']" step="0.01" min="0" max="100" required></label>';echo '<label>Dictamen<select name="sufficient"><option value="1">Suficiente / Aprobado</option><option value="0">No suficiente / Observado</option></select></label><label>Comentarios<textarea name="comments" required minlength="8" maxlength="1000"></textarea></label><button class="button" type="submit">Guardar evaluación</button></form></details>';
            }
            if($def&&$def['status']==='programada'&&(int)$ass['teacher_id']===Auth::id()&&in_array($ass['role_code'],['tutor','tribunal'],true)){
                $hasGrade=Db::one('SELECT grade FROM defense_scores WHERE defense_id=? AND assignment_id=?',[$def['id'],$ass['id']]);
                if($hasGrade)echo '<p class="small-muted">Nota final registrada: '.L::e($hasGrade['grade']).'/100</p>';
                else echo '<details class="form-details"><summary>Registrar nota de defensa</summary><form method="post" action="'.Http::url('defensas/'.$def['id'].'/calificar').'">'.L::csrf().'<input type="hidden" name="assignment_id" value="'.L::e($ass['id']).'"><label>Nota (0–100)<input type="number" name="grade" min="0" max="100" step="0.01" required></label><label>Comentarios<input name="comments" maxlength="700"></label><button class="button" type="submit">Guardar nota final</button></form></details>';
            }
            echo '<a class="table-link" href="'.Http::url('asignaciones/'.$ass['id'].'/carta').'">Descargar carta de designación (PDF de prueba)</a></div>';
        }
        if(!$assignments)echo '<p class="muted">No existen docentes asignados.</p>';
        if($manager){$teachers=Db::all('SELECT t.user_id AS id,u.full_name AS name FROM teachers t JOIN users u ON u.id=t.user_id WHERE u.active=1 ORDER BY u.full_name');$specialties=Db::all('SELECT id,name FROM specialties ORDER BY name');
            echo '<details class="form-details"><summary>Designar tutor, tribunal o revisor</summary><form method="post" action="'.Http::url('postulaciones/'.$id.'/asignar').'">'.L::csrf().'<div class="form-grid"><label>Docente<select name="teacher_id" required>'.L::option($teachers).'</select></label><label>Rol<select name="role_code"><option value="tutor">Tutor</option><option value="tribunal">Tribunal</option><option value="revisor">Revisor de perfil</option></select></label><label>Plaza<select name="seat"><option value="1">1</option><option value="2">2</option></select></label></div><button class="button" type="submit">Confirmar designación</button></form><hr><h4>Sugerencia por carga académica</h4><form method="post" action="'.Http::url('postulaciones/'.$id.'/asignar-auto').'">'.L::csrf().'<div class="form-grid"><label>Rol<select name="role_code"><option value="tutor">Tutor</option><option value="tribunal">Tribunal</option></select></label><label>Plaza<select name="seat"><option value="1">1</option><option value="2">2</option></select></label><label>Especialidad deseada<select name="specialty_id">'.L::option($specialties).'</select></label></div><button class="button secondary" type="submit">Buscar docente de menor carga</button></form></details>';
        }
        echo '</section>';
        echo '<section class="card"><div class="section-heading"><div><h3>Defensa y acta</h3><p>Agenda y resultado final, sujeto a todas las validaciones.</p></div></div>';
        if($binding)echo '<p><a class="button secondary" href="'.Http::url('empastados/'.$binding['id'].'/descargar').'">Descargar autorización de empastado (PDF)</a></p>';
        elseif($manager&&$a['status']==='habilitada'&&(int)$a['requires_profile'])echo '<form method="post" action="'.Http::url('postulaciones/'.$id.'/empastado').'">'.L::csrf().'<button type="submit" class="button secondary">Autorizar empastado del documento final</button></form>';
        if($def){echo '<div class="defense-info"><div><small>Fecha y horario</small><strong>'.L::e($def['starts_at']).' — '.L::e($def['ends_at']).'</strong></div><div><small>Sala</small><strong>'.L::e($def['room_name']).'</strong></div><div><small>Estado</small>'.L::badge($def['status']).'</div></div>';
            if($def['act_id'])echo '<p><a class="button" href="'.Http::url('actas/'.$def['act_id'].'/descargar').'">Descargar acta PDF de demostración · Nota '.L::e($def['final_grade']).'</a></p>';
            elseif($secretariat&&$def['status']==='programada')echo '<form method="post" action="'.Http::url('defensas/'.$def['id'].'/finalizar').'">'.L::csrf().'<button class="button" data-confirm="¿Finalizar defensa? Se generará el acta y no podrás revertir el cierre." type="submit">Cerrar defensa y emitir acta</button></form>';
        }else{echo '<p class="muted">No se ha programado ninguna defensa.</p>';
            if($secretariat&&$a['status']==='habilitada'&&(int)$a['requires_defense']){$rooms=Db::all('SELECT id,name FROM rooms WHERE active=1');echo '<details class="form-details" open><summary>Programar defensa</summary><form method="post" action="'.Http::url('defensas/programar').'">'.L::csrf().'<input type="hidden" name="application_id" value="'.L::e($id).'"><div class="form-grid"><label>Sala<select name="room_id" required>'.L::option($rooms).'</select></label><label>Inicio<input type="datetime-local" name="starts_at" required></label><label>Fin<input type="datetime-local" name="ends_at" required></label></div><button class="button" type="submit">Validar agenda y programar</button></form></details>';
            }
            if(!(int)$a['requires_defense']){
                echo '<div class="notice">La vía de Excelencia Académica se cierra mediante resolución, sin defensa. La nota se registra como dato verificado por Dirección de Carrera.</div>';
                if($resolution)echo '<p><a class="button" href="'.Http::url('resoluciones/'.$resolution['id'].'/descargar').'">Descargar resolución PDF de demostración · Nota '.L::e($resolution['final_grade']).'</a></p>';
                elseif($manager&&$a['status']==='aprobada')echo '<form method="post" action="'.Http::url('postulaciones/'.$id.'/excelencia').'">'.L::csrf().'<label>Promedio académico verificado (0–100)<input type="number" name="grade" min="0" max="100" step="0.01" required></label><label>Fundamento de resolución<textarea name="basis_note" minlength="15" maxlength="800" required placeholder="Registrar evidencia académica y resolución para el prototipo"></textarea></label><button class="button" type="submit" data-confirm="¿Emitir resolución final de prueba?">Generar resolución</button></form>';
            }
        }
        echo '</section></div><aside class="detail-aside"><section class="card"><div class="eyebrow">FICHA ACADÉMICA</div><h3>Datos del expediente</h3><div class="data-row"><span>Estudiante</span><strong>'.L::e($a['student_name']).'</strong></div><div class="data-row"><span>Correo</span><strong>'.L::e($a['student_email']).'</strong></div><div class="data-row"><span>Carrera</span><strong>'.L::e($a['career_name']).'</strong></div><div class="data-row"><span>Modalidad</span><strong>'.L::e($a['modality_name']).'</strong></div><div class="data-row"><span>Convocatoria</span><strong>'.L::e($a['call_title']).'</strong></div><div class="data-row"><span>Límite sin avance</span><strong>'.L::e($a['progress_days']).' días</strong></div></section>';
        $matches=Academic::similarity($a['topic'],$id);echo '<section class="card"><h3>Similitud temática orientativa</h3><p class="muted">Comparación textual de títulos; no es un detector de plagio ni un análisis de contenido.</p>';
        foreach($matches as $match)echo '<div class="similarity"><span>'.L::e($match['topic']).'</span><strong>'.L::e($match['percent']).'%</strong></div>';
        if(!$matches)echo '<p class="small-muted">Sin coincidencias superiores al umbral de orientación (65%).</p>';echo '</section>';
        if($manager&&in_array($a['status'],['presentada','observada'],true))echo '<section class="card"><h3>Resolución del perfil</h3><p class="muted">La aprobación requiere requisitos y versión documental revisados.</p><form method="post" action="'.Http::url('postulaciones/'.$id.'/revisar').'">'.L::csrf().'<label>Decisión<select name="decision"><option value="aprobada">Aprobar postulación</option><option value="observada">Devolver con observaciones</option><option value="rechazada">Rechazar</option></select></label><label>Justificación<textarea name="note" maxlength="1000" rows="3"></textarea></label><button class="button full" type="submit">Guardar resolución</button></form></section>';
        echo '</aside></div>';L::page('Detalle de postulación',ob_get_clean(),'Control documental, evaluación y programación académica.');
    }
    public static function defenses():void {
        Auth::require();$where='';$params=[];
        if(Auth::has('estudiante')){$where='WHERE a.student_id=?';$params[] =Auth::id();}
        elseif(Auth::has('director','secretaria')&&!Auth::has('admin')){$where='WHERE EXISTS(SELECT 1 FROM students st JOIN staff_careers sc ON sc.career_id=st.career_id WHERE st.user_id=a.student_id AND sc.user_id=?)';$params[]=Auth::id();}
        elseif(!Auth::has('admin','director','secretaria')){$where='WHERE EXISTS(SELECT 1 FROM assignments ass WHERE ass.application_id=a.id AND ass.teacher_id=? AND ass.ended_at IS NULL)';$params[]=Auth::id();}
        $rows=Db::all('SELECT d.*,r.name room_name,a.topic,u.full_name student FROM defenses d JOIN rooms r ON r.id=d.room_id JOIN applications a ON a.id=d.application_id JOIN users u ON u.id=a.student_id '.$where.' ORDER BY d.starts_at DESC LIMIT 100',$params);
        ob_start();echo '<section class="card"><div class="section-heading"><div><h2>Calendario de defensas</h2><p>Las fechas y salas se verifican para evitar solapamientos.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Postulante y tema</th><th>Sala</th><th>Estado</th><th></th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.L::e($r['starts_at']).'</td><td><strong>'.L::e($r['student']).'</strong><small class="block">'.L::e($r['topic']).'</small></td><td>'.L::e($r['room_name']).'</td><td>'.L::badge($r['status']).'</td><td><a class="table-link" href="'.Http::url('postulaciones/'.$r['application_id']).'">Ver →</a></td></tr>';if(!$rows)echo '<tr><td colspan="5" class="empty-cell">Sin defensas programadas.</td></tr>';echo '</tbody></table></div></section>';L::page('Agenda de defensas',ob_get_clean(),'Calendario de procesos accesibles para tu rol.');
    }
}
